INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0207-0001-0001-000000000001', '22222222-0002-0001-0001-000000000007', 'Finding Patterns', 'Fibonacci, the rabbit problem, and why patterns are the heartbeat of mathematics', 1, 'tutorial', 15, 5, 1202, 'Leonardo Fibonacci',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0207-0001-0001-000000000001', '33333333-0207-0001-0001-000000000001', 'fill_in_blank', 'easy', 'In the Fibonacci sequence 1, 1, 2, 3, 5, 8, 13, what comes next?', NULL, NULL, '"21"'::jsonb, 'Each Fibonacci number is the sum of the two before it: 8 + 13 = 21.', 'Add the last two numbers together', 5, 1),
('44444444-0207-0001-0001-000000000002', '33333333-0207-0001-0001-000000000001', 'multiple_choice', 'easy', 'What is the rule for generating the Fibonacci sequence?', NULL, '[{"id":"a","text":"Multiply each number by 2"},{"id":"b","text":"Add 3 to each number"},{"id":"c","text":"Each number is the sum of the two before it"},{"id":"d","text":"Square each number"}]'::jsonb, '"c"'::jsonb, 'The Fibonacci rule: each term = previous term + the one before that. So 2+3=5, 3+5=8, 5+8=13, etc.', 'Look at how each number relates to the TWO numbers before it', 5, 2),
('44444444-0207-0001-0001-000000000003', '33333333-0207-0001-0001-000000000001', 'true_false', 'easy', 'True or False: Fibonacci numbers appear in the spiral patterns of sunflower seeds.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Sunflowers typically have 34 spirals going one way and 55 going the other — both Fibonacci numbers.', 'Nature uses these numbers in its designs', 5, 3),
('44444444-0207-0001-0001-000000000004', '33333333-0207-0001-0001-000000000001', 'fill_in_blank', 'easy', 'What is the next number in this pattern: 2, 4, 6, 8, ___?', NULL, NULL, '"10"'::jsonb, 'Each number increases by 2. This is an arithmetic sequence with common difference 2. Next: 8 + 2 = 10.', 'What is being added each time?', 5, 4),
('44444444-0207-0001-0001-000000000005', '33333333-0207-0001-0001-000000000001', 'multiple_choice', 'easy', 'In what year did Fibonacci publish Liber Abaci?', NULL, '[{"id":"a","text":"1066"},{"id":"b","text":"1202"},{"id":"c","text":"1492"},{"id":"d","text":"1637"}]'::jsonb, '"b"'::jsonb, 'Fibonacci published Liber Abaci in 1202, introducing Hindu-Arabic numerals and the famous rabbit problem to Europe.', 'It was in the early 13th century', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0207-0001-0001-000000000002', '22222222-0002-0001-0001-000000000007', 'Arithmetic Sequences', 'Sequences where you add the same number each time', 2, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0207-0002-0001-000000000001', '33333333-0207-0001-0001-000000000002', 'fill_in_blank', 'easy', 'What is the common difference in the sequence 5, 9, 13, 17, 21?', NULL, NULL, '"4"'::jsonb, 'Each term increases by 4: 9-5=4, 13-9=4, 17-13=4. The common difference is 4.', 'Subtract any term from the next one', 5, 1),
('44444444-0207-0002-0001-000000000002', '33333333-0207-0001-0001-000000000002', 'fill_in_blank', 'easy', 'Find the next term: 3, 7, 11, 15, ___', NULL, NULL, '"19"'::jsonb, 'Common difference = 4. Next term = 15 + 4 = 19.', 'Find the common difference, then add it to the last term', 5, 2),
('44444444-0207-0002-0001-000000000003', '33333333-0207-0001-0001-000000000002', 'multiple_choice', 'easy', 'Which of these is an arithmetic sequence?', NULL, '[{"id":"a","text":"1, 2, 4, 8, 16"},{"id":"b","text":"3, 6, 9, 12, 15"},{"id":"c","text":"1, 1, 2, 3, 5"},{"id":"d","text":"1, 4, 9, 16, 25"}]'::jsonb, '"b"'::jsonb, '3, 6, 9, 12, 15 has a constant difference of 3. The others have varying differences (doubling, Fibonacci, and perfect squares).', 'Check if the same number is added each time', 5, 3),
('44444444-0207-0002-0001-000000000004', '33333333-0207-0001-0001-000000000002', 'fill_in_blank', 'easy', 'An arithmetic sequence starts at 10 and has a common difference of -3. What is the 4th term?', NULL, NULL, '"1"'::jsonb, 'Term 1: 10. Term 2: 10+(-3)=7. Term 3: 7+(-3)=4. Term 4: 4+(-3)=1.', 'Keep subtracting 3 from each term', 5, 4),
('44444444-0207-0002-0001-000000000005', '33333333-0207-0001-0001-000000000002', 'fill_in_blank', 'medium', 'The 1st term of an arithmetic sequence is 2 and the common difference is 5. What is the 10th term?', NULL, NULL, '"47"'::jsonb, 'Formula: nth term = first + (n-1) × difference. 10th = 2 + 9 × 5 = 2 + 45 = 47.', 'Use the formula: first term + (n-1) × common difference', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0207-0001-0001-000000000003', '22222222-0002-0001-0001-000000000007', 'Geometric Sequences', 'Sequences where you multiply by the same number each time', 3, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0207-0003-0001-000000000001', '33333333-0207-0001-0001-000000000003', 'fill_in_blank', 'easy', 'What is the common ratio in the sequence 2, 6, 18, 54?', NULL, NULL, '"3"'::jsonb, 'Each term is multiplied by 3: 2×3=6, 6×3=18, 18×3=54. The common ratio is 3.', 'Divide any term by the previous one', 5, 1),
('44444444-0207-0003-0001-000000000002', '33333333-0207-0001-0001-000000000003', 'fill_in_blank', 'easy', 'Find the next term: 5, 10, 20, 40, ___', NULL, NULL, '"80"'::jsonb, 'Common ratio = 2 (each term doubles). Next: 40 × 2 = 80.', 'Each number is multiplied by the same value', 5, 2),
('44444444-0207-0003-0001-000000000003', '33333333-0207-0001-0001-000000000003', 'multiple_choice', 'easy', 'Which is a geometric sequence?', NULL, '[{"id":"a","text":"2, 4, 6, 8"},{"id":"b","text":"3, 9, 27, 81"},{"id":"c","text":"1, 3, 5, 7"},{"id":"d","text":"10, 7, 4, 1"}]'::jsonb, '"b"'::jsonb, '3, 9, 27, 81 — each multiplied by 3. The others add a constant (arithmetic), not multiply.', 'Check if each term is multiplied by the same number', 5, 3),
('44444444-0207-0003-0001-000000000004', '33333333-0207-0001-0001-000000000003', 'fill_in_blank', 'easy', 'A geometric sequence starts at 100 with common ratio 1/2. What is the 3rd term?', NULL, NULL, '"25"'::jsonb, 'Term 1: 100. Term 2: 100 × 0.5 = 50. Term 3: 50 × 0.5 = 25.', 'Keep halving each term', 5, 4),
('44444444-0207-0003-0001-000000000005', '33333333-0207-0001-0001-000000000003', 'true_false', 'easy', 'True or False: The sequence 1, -2, 4, -8, 16 is geometric with a common ratio of -2.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Each term is multiplied by -2: 1×(-2)=-2, -2×(-2)=4, 4×(-2)=-8. The alternating signs come from the negative ratio.', 'Divide consecutive terms: -2/1, 4/(-2), -8/4', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0207-0001-0001-000000000004', '22222222-0002-0001-0001-000000000007', 'Patterns Boss Round', 'Master patterns and sequences!', 4, 'boss_round', 25, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0207-0004-0001-000000000001', '33333333-0207-0001-0001-000000000004', 'fill_in_blank', 'medium', 'What are the next TWO Fibonacci numbers after 21, 34? (Write as X, Y)', NULL, NULL, '"55, 89"'::jsonb, '21 + 34 = 55, then 34 + 55 = 89. The Fibonacci sequence continues: ...21, 34, 55, 89, 144...', 'Add the last two to get the next, then repeat', 10, 1),
('44444444-0207-0004-0001-000000000002', '33333333-0207-0001-0001-000000000004', 'multiple_choice', 'medium', 'Is the sequence 4, 12, 36, 108 arithmetic or geometric?', NULL, '[{"id":"a","text":"Arithmetic (common difference 8)"},{"id":"b","text":"Geometric (common ratio 3)"},{"id":"c","text":"Neither"},{"id":"d","text":"Both"}]'::jsonb, '"b"'::jsonb, 'Check: 12/4=3, 36/12=3, 108/36=3. Constant ratio of 3 = geometric. The differences (8, 24, 72) are NOT constant, so it is not arithmetic.', 'Try dividing consecutive terms', 10, 2),
('44444444-0207-0004-0001-000000000003', '33333333-0207-0001-0001-000000000004', 'fill_in_blank', 'medium', 'Find the 20th term of the arithmetic sequence: 3, 8, 13, 18... (Type just the number)', NULL, NULL, '"98"'::jsonb, 'Common difference = 5. 20th term = 3 + (20-1) × 5 = 3 + 95 = 98.', 'Use: first term + (n-1) × common difference', 10, 3),
('44444444-0207-0004-0001-000000000004', '33333333-0207-0001-0001-000000000004', 'multiple_choice', 'medium', 'Indian mathematicians studied the Fibonacci sequence centuries before Fibonacci. Who among these described it in the context of Sanskrit poetry?', NULL, '[{"id":"a","text":"Aryabhata"},{"id":"b","text":"Brahmagupta"},{"id":"c","text":"Hemachandra"},{"id":"d","text":"Ramanujan"}]'::jsonb, '"c"'::jsonb, 'Hemachandra (1150 CE) described the sequence in his study of Sanskrit poetic meters — about 50 years before Fibonacci''s Liber Abaci (1202).', 'He studied poetry patterns in the 12th century', 10, 4),
('44444444-0207-0004-0001-000000000005', '33333333-0207-0001-0001-000000000004', 'fill_in_blank', 'medium', 'A geometric sequence has first term 2 and common ratio 4. What is the 5th term?', NULL, NULL, '"512"'::jsonb, 'Term 1: 2. Term 2: 8. Term 3: 32. Term 4: 128. Term 5: 512. Or use formula: 2 × 4^4 = 2 × 256 = 512.', 'Keep multiplying by 4, or use: first × ratio^(n-1)', 10, 5)
